PRAGMA auto_vacuum = INCREMENTAL;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "arabic_parts" (
	"id"	INTEGER,
	"name"	TEXT NOT NULL UNIQUE,
	"gender_id"	INTEGER NOT NULL,
	"diurnal_personal_point"	INTEGER NOT NULL,
	"diurnal_significator"	INTEGER NOT NULL,
	"diurnal_trigger"	INTEGER NOT NULL,
	"nocturnal_personal_point"	INTEGER NOT NULL,
	"nocturnal_significator"	INTEGER NOT NULL,
	"nocturnal_trigger"	INTEGER NOT NULL,
	"link"	TEXT,
	"link2"	TEXT,
	"description"	TEXT,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("diurnal_personal_point") REFERENCES "objects"("id"),
	FOREIGN KEY("diurnal_significator") REFERENCES "objects"("id"),
	FOREIGN KEY("diurnal_trigger") REFERENCES "objects"("id"),
	FOREIGN KEY("gender_id") REFERENCES "gender"("id"),
	FOREIGN KEY("nocturnal_personal_point") REFERENCES "objects"("id"),
	FOREIGN KEY("nocturnal_significator") REFERENCES "objects"("id"),
	FOREIGN KEY("nocturnal_trigger") REFERENCES "objects"("id")
);
CREATE TABLE IF NOT EXISTS "charts" (
	"chart_name"	TEXT NOT NULL,
	"year"	INTEGER,
	"month"	INTEGER,
	"day"	INTEGER,
	"hour"	INTEGER,
	"min"	INTEGER,
	"sec"	REAL,
	"dst"	INTEGER,
	"tz_offset"	REAL,
	"dst_offset"	REAL,
	"country"	TEXT,
	"state"	TEXT,
	"city"	TEXT,
	"city_id"	INTEGER,
	"gender"	INTEGER,
	PRIMARY KEY("chart_name"),
	FOREIGN KEY("gender") REFERENCES "gender"("id")
);
CREATE TABLE IF NOT EXISTS "cities" (
	"id"	INTEGER,
	"city"	TEXT,
	"state_id"	INTEGER,
	"state_code"	TEXT,
	"state"	TEXT,
	"country_id"	INTEGER,
	"country_code"	TEXT,
	"country"	TEXT,
	"lat"	REAL,
	"lon"	REAL,
	"elev"	REAL,
	"native"	TEXT,
	"type"	TEXT,
	"level"	INTEGER,
	"parent_id"	INTEGER,
	"population"	INTEGER,
	"timezone"	TEXT,
	"wikiDataId"	INTEGER,
	"gmt_offset_standard"	TEXT,
	"gmt_offset_secs"	INTEGER,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "elements" (
	"id"	INTEGER NOT NULL,
	"symbol"	TEXT NOT NULL,
	"name"	TEXT,
	"ruler1"	INTEGER,
	"ruler2"	INTEGER,
	"ruler3"	INTEGER,
	"description"	TEXT,
	"temperature"	INTEGER,
	"moisture"	INTEGER,
	PRIMARY KEY("id"),
	FOREIGN KEY("moisture") REFERENCES "moisture"("id"),
	FOREIGN KEY("ruler1") REFERENCES "planets"("id"),
	FOREIGN KEY("ruler2") REFERENCES "planets"("id"),
	FOREIGN KEY("ruler3") REFERENCES "planets"("id"),
	FOREIGN KEY("temperature") REFERENCES "temperature"("id")
);
CREATE TABLE IF NOT EXISTS "gender" (
	"id"	INTEGER NOT NULL,
	"name"	TEXT NOT NULL,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "house_latitude" (
	"id"	TEXT NOT NULL,
	"description"	TEXT,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "house_longitude" (
	"id"	TEXT NOT NULL,
	"description"	TEXT,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "house_system" (
	"id"	TEXT NOT NULL,
	"name"	TEXT,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "houses" (
	"id"	INTEGER NOT NULL,
	"latin_title"	TEXT,
	"title"	TEXT,
	"position"	INTEGER,
	"latitude"	INTEGER,
	"longitude"	INTEGER,
	"meaning"	TEXT,
	"quadrant"	INTEGER,
	PRIMARY KEY("id"),
	FOREIGN KEY("latitude") REFERENCES "house_latitude"("id"),
	FOREIGN KEY("longitude") REFERENCES "house_longitude"("id"),
	FOREIGN KEY("position") REFERENCES "position"("id"),
	FOREIGN KEY("quadrant") REFERENCES "quadrant"("id")
);
CREATE TABLE IF NOT EXISTS "key_type" (
	"id"	INTEGER NOT NULL UNIQUE,
	"name"	TEXT NOT NULL UNIQUE,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "languages" (
	"cod"	TEXT,
	"name"	TEXT,
	PRIMARY KEY("cod")
);
CREATE TABLE IF NOT EXISTS "mode" (
	"id"	INTEGER NOT NULL,
	"name"	TEXT,
	"description"	TEXT,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "moisture" (
	"id"	INTEGER,
	"name"	TEXT,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "moon_phases" (
	"id"	INTEGER NOT NULL,
	"phase_name"	TEXT,
	"phase_display"	TEXT,
	"quarter"	INTEGER,
	"temperament"	INTEGER,
	PRIMARY KEY("id"),
	FOREIGN KEY("temperament") REFERENCES "temperament"("id")
);
CREATE TABLE IF NOT EXISTS "object_type" (
	"id"	INTEGER,
	"type"	TEXT,
	"description"	TEXT,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "objects" (
	"id"	INTEGER,
	"symbol"	TEXT,
	"name"	TEXT,
	"force"	REAL,
	"type"	INTEGER,
	"fixed_longitude"	REAL,
	"object_ref"	INTEGER,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("object_ref") REFERENCES "objects"("id"),
	FOREIGN KEY("type") REFERENCES "object_type"("id")
);
CREATE TABLE IF NOT EXISTS "old_cities" (
	"city"	TEXT NOT NULL,
	"city_ascii"	TEXT NOT NULL,
	"lat"	REAL NOT NULL,
	"lng"	REAL NOT NULL,
	"elev"	REAL,
	"country"	TEXT NOT NULL,
	"iso2"	TEXT,
	"iso3"	TEXT,
	"state"	TEXT,
	"capital"	TEXT,
	"population"	INTEGER,
	"id"	INTEGER NOT NULL,
	"timezone"	TEXT,
	"gmt_offset_standard"	TEXT,
	"gmt_offset_secs"	INTEGER,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "orientality" (
	"id"	INTEGER,
	"name"	TEXT,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "pd_arc_calc" (
	"id"	INTEGER,
	"name"	TEXT,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "pd_aspects_latitude" (
	"id"	INTEGER,
	"aspects"	TEXT,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "pd_zod_latitude" (
	"id"	INTEGER,
	"description"	TEXT,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "planets" (
	"id"	INTEGER NOT NULL,
	"name"	TEXT NOT NULL,
	"symbol"	TEXT NOT NULL,
	"orbis"	REAL,
	"speed"	REAL,
	"gender"	INTEGER,
	"sect"	INTEGER,
	"domicile_day"	INTEGER,
	"domicile_night"	INTEGER,
	"exaltation"	INTEGER,
	"meaning"	TEXT,
	"temperature"	INTEGER,
	"moisture"	INTEGER,
	"orientality"	INTEGER,
	"lesser_years"	INTEGER,
	"middle_years"	INTEGER,
	"greater_years"	INTEGER,
	PRIMARY KEY("id"),
	FOREIGN KEY("domicile_day") REFERENCES "signs"("id"),
	FOREIGN KEY("domicile_night") REFERENCES "signs"("id"),
	FOREIGN KEY("exaltation") REFERENCES "signs"("id"),
	FOREIGN KEY("gender") REFERENCES "gender"("id"),
	FOREIGN KEY("moisture") REFERENCES "moisture"("id"),
	FOREIGN KEY("orientality") REFERENCES "orientality"("id"),
	FOREIGN KEY("sect") REFERENCES "sect"("id"),
	FOREIGN KEY("temperature") REFERENCES "temperature"("id")
);
CREATE TABLE IF NOT EXISTS "position" (
	"id"	INTEGER NOT NULL,
	"name"	TEXT NOT NULL,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "profiles" (
	"id"	INTEGER NOT NULL,
	"profile"	TEXT NOT NULL,
	"dst"	INTEGER DEFAULT -1,
	"dark_mode"	INTEGER DEFAULT 0,
	"house_system"	TEXT DEFAULT 'P',
	"triplicity_system"	INTEGER DEFAULT 1,
	"terms_system"	INTEGER DEFAULT 1,
	"parallel_orbis"	REAL,
	"antissia_orb"	REAL,
	"modern_planets_rulling"	INTEGER DEFAULT 1,
	"city_id"	INTEGER,
	"show_modern_planets"	INTEGER DEFAULT 1,
	"gender"	INTEGER,
	"language"	TEXT DEFAULT 'en',
	"time_key"	INTEGER,
	"antiscia_as_promissor"	INTEGER DEFAULT 0,
	"zod_pd_with_lat"	INTEGER DEFAULT 1,
	"pd_arc_calc"	INTEGER DEFAULT 1,
	PRIMARY KEY("id"),
	FOREIGN KEY("city_id") REFERENCES "cities"("id"),
	FOREIGN KEY("gender") REFERENCES "gender"("id"),
	FOREIGN KEY("house_system") REFERENCES "house_system"("id"),
	FOREIGN KEY("language") REFERENCES "languages"("cod"),
	FOREIGN KEY("pd_arc_calc") REFERENCES "pd_arc_calc"("id"),
	FOREIGN KEY("terms_system") REFERENCES "terms_systems"("id"),
	FOREIGN KEY("time_key") REFERENCES "time_keys"("id"),
	FOREIGN KEY("triplicity_system") REFERENCES "triplicity_systems"("id"),
	FOREIGN KEY("zod_pd_with_lat") REFERENCES "pd_zod_latitude"("id")
);
CREATE TABLE IF NOT EXISTS "quadrant" (
	"id"	INTEGER,
	"name"	TEXT,
	"gender"	INTEGER,
	"temperament"	INTEGER,
	PRIMARY KEY("id"),
	FOREIGN KEY("gender") REFERENCES "gender"("id"),
	FOREIGN KEY("temperament") REFERENCES "temperament"("id")
);
CREATE TABLE IF NOT EXISTS "seasons" (
	"id"	INTEGER,
	"name"	TEXT,
	"element"	INTEGER,
	PRIMARY KEY("id"),
	FOREIGN KEY("element") REFERENCES "elements"("id")
);
CREATE TABLE IF NOT EXISTS "sect" (
	"id"	INTEGER NOT NULL,
	"name"	TEXT NOT NULL,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "signs" (
	"id"	INTEGER NOT NULL,
	"symbol"	TEXT NOT NULL,
	"name"	TEXT NOT NULL,
	"ruler"	INTEGER,
	"exalted"	INTEGER,
	"exile"	INTEGER,
	"fall"	INTEGER,
	"opposite_sign"	INTEGER,
	"mode"	INTEGER,
	"gender"	INTEGER,
	"element"	INTEGER,
	"season"	INTEGER,
	"description"	TEXT,
	PRIMARY KEY("id"),
	FOREIGN KEY("element") REFERENCES "elements"("id"),
	FOREIGN KEY("exalted") REFERENCES "planets"("id"),
	FOREIGN KEY("exile") REFERENCES "planets"("id"),
	FOREIGN KEY("fall") REFERENCES "planets"("id"),
	FOREIGN KEY("gender") REFERENCES "gender"("id"),
	FOREIGN KEY("mode") REFERENCES "mode"("id"),
	FOREIGN KEY("opposite_sign") REFERENCES "signs"("id"),
	FOREIGN KEY("ruler") REFERENCES "planets"("id"),
	FOREIGN KEY("season") REFERENCES "seasons"("id")
);
CREATE TABLE IF NOT EXISTS "temperament" (
	"id"	INTEGER NOT NULL,
	"name"	TEXT,
	"description"	TEXT,
	"element"	INTEGER,
	PRIMARY KEY("id"),
	FOREIGN KEY("element") REFERENCES "elements"("id")
);
CREATE TABLE IF NOT EXISTS "temperature" (
	"id"	INTEGER,
	"name"	TEXT,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "terms_systems" (
	"id"	INTEGER,
	"name"	TEXT,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "time_keys" (
	"id"	INTEGER NOT NULL UNIQUE,
	"name"	TEXT NOT NULL UNIQUE,
	"type"	INTEGER,
	"value"	REAL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("type") REFERENCES "key_type"("id")
);
CREATE TABLE IF NOT EXISTS "triplicity_rulers" (
	"id"	INTEGER NOT NULL,
	"system"	INTEGER,
	"element"	INTEGER,
	"ruler1"	INTEGER,
	"ruler2"	INTEGER,
	"ruler3"	INTEGER,
	PRIMARY KEY("id"),
	FOREIGN KEY("element") REFERENCES "elements"("id"),
	FOREIGN KEY("ruler1") REFERENCES "planets"("id"),
	FOREIGN KEY("ruler2") REFERENCES "planets"("id"),
	FOREIGN KEY("ruler3") REFERENCES "planets"("id"),
	FOREIGN KEY("system") REFERENCES "triplicity_systems"("id")
);
CREATE TABLE IF NOT EXISTS "triplicity_systems" (
	"id"	INTEGER NOT NULL,
	"name"	TEXT,
	PRIMARY KEY("id")
);
CREATE INDEX idx_chart_search ON charts (chart_name COLLATE GLOBAL_SEM_ACENTO);
CREATE INDEX idx_city_search ON cities (country, state COLLATE GLOBAL_SEM_ACENTO, city COLLATE GLOBAL_SEM_ACENTO);
COMMIT;
